export function invitationMessage(name,url){return `🤎 CONVITE DE CASAMENTO\n\nOlá, ${name}!\n\nCom muita alegria, Aniceta Martins e Kerusso Truth Perhay convidam você para celebrar o seu casamento, no dia 20 de Fevereiro de 2027.\n\nSerá um dia de amor, fé e confraternização, e a sua presença tornará este momento ainda mais especial.\n\n🤍 Cerimónia: Igreja Arco-Íris de Zimpeto · 10h00\n🥂 Recepção: Cajada 1 · 13h00\n\nAbra o seu convite pessoal para consultar os detalhes, as orientações de vestuário e confirmar a sua presença:\n\n${url}\n\nEste convite é pessoal e intransferível, destinado exclusivamente a você.\n\nCom carinho,\nAniceta & Kerusso 🤎`;}
